const payload = $json.body ?? $json;
const headers = $json.headers ?? {};

const expectedToken = String($env.INTERNAL_API_TOKEN ?? '').trim();
const providedToken = String(headers['x-internal-token'] ?? headers['X-Internal-Token'] ?? '').trim();
if (!expectedToken || providedToken !== expectedToken) {
  throw new Error('Invalid internal token on unified workflow request');
}

const jobId = String(payload.jobId ?? '').trim();
if (!jobId) {
  throw new Error('jobId is required');
}

const executionMode = String(payload.executionMode ?? '').trim().toLowerCase();
if (!executionMode) {
  throw new Error('executionMode is required and must be sync|batch');
}
if (!['sync', 'batch'].includes(executionMode)) {
  throw new Error(`executionMode must be sync|batch, got '${executionMode}'`);
}

const batchStrategy = String(payload.batchStrategy ?? '').trim().toLowerCase();
if (!batchStrategy) {
  throw new Error('batchStrategy is required and must be count_only');
}
if (batchStrategy !== 'count_only') {
  throw new Error(`batchStrategy must be count_only, got '${batchStrategy}'`);
}

const appBase = String($env.APP_INTERNAL_BASE_URL ?? 'http://app:8080').replace(/\/+$/, '');
const openaiKey = String($env.OPENAI_API_KEY ?? '').trim();
const openaiModel = String($env.OPENAI_MODEL ?? 'gpt-4.1-mini').trim();
const completionWindow = String($env.OPENAI_BATCH_COMPLETION_WINDOW ?? '24h').trim();
const maxBatchSize = Math.max(1, Number($env.MAX_BATCH_SIZE ?? 20));
const maxWaitSeconds = Math.max(1, Number($env.MAX_WAIT_SECONDS ?? 60));

if (!openaiKey) {
  throw new Error('OPENAI_API_KEY is required in n8n environment.');
}

const escapeSql = (v) => String(v ?? '').replace(/'/g, "''");

return [{
  json: {
    jobId,
    jobIdSql: escapeSql(jobId),
    executionMode,
    batchStrategy,
    appBase,
    expectedToken,
    openaiKey,
    openaiModel,
    completionWindow,
    maxBatchSize,
    maxWaitSeconds,
    appBaseSql: escapeSql(appBase),
    expectedTokenSql: escapeSql(expectedToken),
    openaiKeySql: escapeSql(openaiKey),
    openaiModelSql: escapeSql(openaiModel),
    completionWindowSql: escapeSql(completionWindow),
    batchStrategySql: escapeSql(batchStrategy)
  }
}];

const ctx = $node['Validate + Build Context'].json;

const jobId = String(ctx.jobId ?? '').trim();
const appBase = String(ctx.appBase ?? 'http://app:8080').replace(/\/+$/, '');
const expectedToken = String(ctx.expectedToken ?? '').trim();
const openaiKey = String(ctx.openaiKey ?? '').trim();
const model = String(ctx.openaiModel ?? 'gpt-4.1-mini').trim();
const inputPrice = Number($env.OPENAI_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const outputPrice = Number($env.OPENAI_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');

if (!jobId || !appBase || !expectedToken || !openaiKey) {
  return [{ json: { ok: false, jobId, errorMessage: 'Missing sync context (job/app/token/openai key)' } }];
}

const errText = (error, prefix) => {
  const body = error?.response?.body ?? error?.context ?? error?.data ?? null;
  const extra = body ? ` | details=${JSON.stringify(body).slice(0, 500)}` : '';
  return `${prefix}: ${String(error?.message ?? error).slice(0, 500)}${extra}`;
};

try {
  let uploadResult;
  try {
    uploadResult = await this.helpers.httpRequest({
      method: 'POST',
      url: `${appBase}/api/internal/jobs/${encodeURIComponent(jobId)}/openai-file`,
      headers: {
        'x-internal-token': expectedToken,
        'Content-Type': 'application/json',
      },
      body: { purpose: 'user_data' },
      json: true,
    });
  } catch (error) {
    return [{ json: { ok: false, jobId, errorMessage: errText(error, 'OpenAI file upload failed') } }];
  }

  const inputFileId = String(uploadResult?.file?.id ?? uploadResult?.id ?? '').trim();
  if (!inputFileId) {
    return [{
      json: {
        ok: false,
        jobId,
        errorMessage: `OpenAI file upload returned no file id: ${JSON.stringify(uploadResult).slice(0, 300)}`,
      },
    }];
  }

  const responsesRequest = {
    model,
    input: [
      {
        role: 'system',
        content: [
          {
            type: 'input_text',
            text: 'You are a concise technical summarizer. Summarize the document in 6-10 bullet points and end with one-paragraph executive summary.',
          },
        ],
      },
      {
        role: 'user',
        content: [
          { type: 'input_file', file_id: inputFileId },
          { type: 'input_text', text: 'Summarize this PDF document.' },
        ],
      },
    ],
    max_output_tokens: 550,
    metadata: {
      template: 'template_2',
      job_id: jobId,
    },
  };

  return [{
    json: {
      ok: true,
      jobId,
      appBase,
      expectedToken,
      openaiKey,
      model,
      inputPrice,
      outputPrice,
      startedAt: Date.now(),
      responsesRequest,
    },
  }];
} catch (error) {
  return [{ json: { ok: false, jobId, errorMessage: errText(error, 'Sync prepare failed') } }];
}

const prepared = $node['Sync Prepare Input File'].json ?? {};
const ctx = $node['Validate + Build Context'].json ?? {};

const jobId = String(prepared.jobId ?? ctx.jobId ?? '').trim();
const model = String(prepared.model ?? ctx.openaiModel ?? 'gpt-4.1-mini').trim();

if (!prepared.ok) {
  return [{ json: { ok: false, jobId, model, errorMessage: String(prepared.errorMessage ?? 'Sync prepare failed') } }];
}

try {
  const raw = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/responses',
    headers: {
      Authorization: `Bearer ${prepared.openaiKey}`,
      'Content-Type': 'application/json',
    },
    body: prepared.responsesRequest,
    json: true,
  });

  return [{
    json: {
      ok: true,
      jobId,
      model,
      openaiRequestId: String(raw?.id ?? '').trim(),
      raw,
    }
  }];
} catch (error) {
  const details = error?.response?.body ?? error?.context ?? error?.data ?? null;
  const errorMessage = `OpenAI responses failed: ${String(error?.message ?? error).slice(0, 500)}${details ? ` | details=${JSON.stringify(details).slice(0, 500)}` : ''}`;
  return [{
    json: {
      ok: false,
      jobId,
      model,
      errorMessage
    }
  }];
}

const prepared = $node['Sync Prepare Input File'].json ?? {};
const execution = $node['Sync OpenAI Responses'].json ?? {};
const ctx = $node['Validate + Build Context'].json ?? {};

const jobId = String(prepared.jobId ?? execution.jobId ?? ctx.jobId ?? '').trim();
const model = String(execution.model ?? prepared.model ?? ctx.openaiModel ?? 'gpt-4.1-mini').trim();
const inputPrice = Number(prepared.inputPrice ?? $env.OPENAI_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? 0);
const outputPrice = Number(prepared.outputPrice ?? $env.OPENAI_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? 0);
const startedAt = Number(prepared.startedAt ?? Date.now());

const parseOutputText = (raw) => {
  if (!raw || typeof raw !== 'object') return '';
  if (typeof raw.output_text === 'string' && raw.output_text.trim()) return raw.output_text.trim();
  const output = Array.isArray(raw.output) ? raw.output : [];
  const parts = [];
  for (const item of output) {
    const content = Array.isArray(item?.content) ? item.content : [];
    for (const piece of content) {
      if (piece?.type === 'output_text' && typeof piece.text === 'string') {
        parts.push(piece.text);
      }
    }
  }
  return parts.join('\n').trim();
};

const estimateCost = (inTokens, outTokens) => {
  const inputCost = (Number(inTokens) / 1_000_000) * Number(inputPrice);
  const outputCost = (Number(outTokens) / 1_000_000) * Number(outputPrice);
  return Number((inputCost + outputCost).toFixed(6));
};

const escapeSql = (v) => String(v ?? '').replace(/'/g, "''");

if (!prepared.ok) {
  const errorMessage = String(prepared.errorMessage ?? 'Sync prepare failed');
  return [{
    json: {
      ok: false,
      jobId,
      jobIdSql: escapeSql(jobId),
      errorMessage,
      errorMessageSql: escapeSql(errorMessage)
    }
  }];
}

if (!execution.ok) {
  const errorMessage = String(execution.errorMessage ?? 'OpenAI responses failed');
  return [{
    json: {
      ok: false,
      jobId,
      jobIdSql: escapeSql(jobId),
      errorMessage,
      errorMessageSql: escapeSql(errorMessage)
    }
  }];
}

const raw = execution.raw ?? {};
const summaryText = parseOutputText(raw) || 'No summary generated.';
const usage = raw.usage ?? {};
const inputTokens = Number(usage.input_tokens ?? 0);
const outputTokens = Number(usage.output_tokens ?? 0);
const totalTokens = Number(usage.total_tokens ?? (inputTokens + outputTokens));
const openaiRequestId = String(execution.openaiRequestId ?? raw.id ?? '').trim();
const latencyMs = Math.max(1, Date.now() - startedAt);
const costEstUsd = estimateCost(inputTokens, outputTokens);

return [{
  json: {
    ok: true,
    jobId,
    jobIdSql: escapeSql(jobId),
    openaiRequestId,
    openaiRequestIdSql: escapeSql(openaiRequestId),
    summaryText,
    summaryTextSql: escapeSql(summaryText),
    model,
    modelSql: escapeSql(model),
    inputTokens,
    outputTokens,
    totalTokens,
    latencyMs,
    costEstUsd,
    rawJsonSql: escapeSql(JSON.stringify(raw))
  }
}];

const rows = $input.all().map((i) => i.json ?? {}).filter(Boolean);
if (rows.length === 0) return [{ json: { hasBatch: false } }];

const base = $node['Validate + Build Context'].json ?? {};
const first = rows[0];
const appBase = String(first.app_base ?? base.appBase ?? '').trim();
const expectedToken = String(first.expected_token ?? base.expectedToken ?? '').trim();
const openaiKey = String(first.openai_key ?? base.openaiKey ?? '').trim();
const openaiModel = String(first.openai_model ?? base.openaiModel ?? 'gpt-4.1-mini').trim();
const completionWindow = String(first.completion_window ?? base.completionWindow ?? '24h').trim();
const batchStrategy = String(base.batchStrategy ?? 'count_only').trim().toLowerCase();
const maxBatchSize = Math.max(1, Number(base.maxBatchSize ?? 20));
const maxWaitSeconds = Math.max(1, Number(base.maxWaitSeconds ?? 60));

if (!appBase || !expectedToken || !openaiKey) throw new Error('Missing app/openai context for batch prepare stage');

const jobRows = rows
  .map((r) => ({ jobId: String(r.job_id ?? '').trim(), filename: String(r.filename ?? '').trim() || 'document.pdf' }))
  .filter((r) => r.jobId);
if (jobRows.length === 0) return [{ json: { hasBatch: false } }];

const jobMap = new Map(jobRows.map((row) => [row.jobId, row]));
const candidateJobIds = [...jobMap.keys()];

const errText = (error, prefix) => {
  const body = error?.response?.body ?? error?.context ?? error?.data ?? null;
  const extra = body ? ` | details=${JSON.stringify(body).slice(0, 500)}` : '';
  return `${prefix}: ${String(error?.message ?? error).slice(0, 500)}${extra}`;
};

let openResult;
try {
  openResult = await this.helpers.httpRequest({
    method: 'POST',
    url: `${appBase}/api/internal/batches/open`,
    headers: {
      'x-internal-token': expectedToken,
      'Content-Type': 'application/json',
    },
    body: {
      strategy: batchStrategy,
      jobIds: candidateJobIds,
      maxBatchSize,
      maxWaitSeconds,
    },
    json: true,
  });
} catch (error) {
  const statusCode = Number(error?.statusCode ?? error?.response?.statusCode ?? 0);
  if (statusCode === 409) {
    return [{ json: { hasBatch: false, reason: 'no_eligible_jobs' } }];
  }
  throw new Error(errText(error, 'Atomic batch claim failed'));
}

const batchId = String(openResult?.batch?.id ?? '').trim();
const claimedJobIds = Array.isArray(openResult?.jobIds)
  ? openResult.jobIds.map((id) => String(id ?? '').trim()).filter(Boolean)
  : [];

if (!batchId || claimedJobIds.length === 0) {
  return [{ json: { hasBatch: false, reason: 'empty_claim' } }];
}

const claimedRows = claimedJobIds.map((id) => jobMap.get(id)).filter(Boolean);
if (claimedRows.length === 0) {
  throw new Error('Atomic claim returned job ids outside current candidate list');
}

const jsonlLines = [];
for (const item of claimedRows) {
  let uploadResult;
  try {
    uploadResult = await this.helpers.httpRequest({
      method: 'POST',
      url: `${appBase}/api/internal/jobs/${encodeURIComponent(item.jobId)}/openai-file`,
      headers: {
        'x-internal-token': expectedToken,
        'Content-Type': 'application/json',
      },
      body: { purpose: 'user_data' },
      json: true,
    });
  } catch (error) {
    throw new Error(errText(error, `OpenAI user_data upload failed for job ${item.jobId}`));
  }

  const fileId = String(uploadResult?.file?.id ?? uploadResult?.id ?? '').trim();
  if (!fileId) {
    throw new Error(`OpenAI user_data upload returned no file id for job ${item.jobId}: ${JSON.stringify(uploadResult).slice(0, 300)}`);
  }

  jsonlLines.push(JSON.stringify({
    custom_id: item.jobId,
    method: 'POST',
    url: '/v1/responses',
    body: {
      model: openaiModel,
      input: [
        {
          role: 'system',
          content: [{ type: 'input_text', text: 'You are a concise technical summarizer. Summarize the document in 6-10 bullet points and end with one-paragraph executive summary.' }],
        },
        {
          role: 'user',
          content: [
            { type: 'input_file', file_id: fileId },
            { type: 'input_text', text: 'Summarize this PDF document.' },
          ],
        },
      ],
      max_output_tokens: 550,
      metadata: { template: 'template_2', batch_id: batchId, job_id: item.jobId },
    },
  }));
}

let inputUploadResult;
try {
  inputUploadResult = await this.helpers.httpRequest({
    method: 'POST',
    url: `${appBase}/api/internal/openai/files/upload-text`,
    headers: {
      'x-internal-token': expectedToken,
      'Content-Type': 'application/json',
    },
    body: {
      purpose: 'batch',
      filename: `batch-${batchId}.jsonl`,
      contentType: 'application/jsonl',
      content: `${jsonlLines.join('\n')}\n`,
    },
    json: true,
  });
} catch (error) {
  throw new Error(errText(error, 'OpenAI batch input upload failed'));
}

const inputFileId = String(inputUploadResult?.file?.id ?? inputUploadResult?.id ?? '').trim();
if (!inputFileId) {
  throw new Error(`OpenAI batch input upload returned no id: ${JSON.stringify(inputUploadResult).slice(0, 300)}`);
}

return [{
  json: {
    hasBatch: true,
    batchId,
    appBase,
    expectedToken,
    openaiKey,
    openaiModel,
    completionWindow,
    inputFileId,
    jobsSubmitted: claimedRows.length,
    setupSql: 'SELECT 1;',
  },
}];

const base = $node['Prepare + Submit OpenAI Batch'].json;
const statusCode = Number($json.statusCode ?? $json.status ?? 0);
const raw = $json.body ?? $json;

const batchId = String(base.batchId ?? '').trim();
const inputFileId = String(base.inputFileId ?? '').trim();
const escapeSql = (v) => String(v ?? '').replace(/'/g, "''");

const shared = {
  batchId,
  appBase: base.appBase,
  expectedToken: base.expectedToken,
  openaiKey: base.openaiKey,
  openaiModel: base.openaiModel
};

if (!batchId) {
  return [{
    json: {
      ...shared,
      openaiBatchId: '',
      batchCreated: false,
      prePollSql: 'SELECT 1;'
    }
  }];
}

if ($json.error || statusCode >= 400 || statusCode < 200) {
  const message = escapeSql(String(($json.error && JSON.stringify($json.error)) || JSON.stringify(raw) || `OpenAI batch create failed (${statusCode || 'unknown'})`).slice(0, 900));
  return [{
    json: {
      ...shared,
      openaiBatchId: '',
      batchCreated: false,
      prePollSql: `UPDATE batch_windows SET status='failed', completed_at=NOW() WHERE id='${escapeSql(batchId)}';\nUPDATE summary_jobs SET status='failed', error_message='${message}', completed_at=NOW(), updated_at=NOW() WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','batched','processing');\nUPDATE batch_items SET status='failed' WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','processing');`
    }
  }];
}

const openaiBatchId = String(raw.id ?? '').trim();
if (!openaiBatchId) {
  return [{
    json: {
      ...shared,
      openaiBatchId: '',
      batchCreated: false,
      prePollSql: `UPDATE batch_windows SET status='failed', completed_at=NOW() WHERE id='${escapeSql(batchId)}';`
    }
  }];
}

const sql = `UPDATE batch_windows SET status='processing', openai_batch_id='${escapeSql(openaiBatchId)}', input_file_id=COALESCE(input_file_id,NULLIF('${escapeSql(inputFileId)}','')) WHERE id='${escapeSql(batchId)}';\nUPDATE summary_jobs SET status='processing', started_at=COALESCE(started_at,NOW()), openai_batch_id='${escapeSql(openaiBatchId)}', updated_at=NOW() WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','batched');\nUPDATE batch_items SET status='processing' WHERE batch_id='${escapeSql(batchId)}' AND status='queued';`;

return [{
  json: {
    ...shared,
    openaiBatchId,
    batchCreated: true,
    prePollSql: sql
  }
}];

const base = $node['Parse Batch Create Response'].json;
const batchId = String(base.batchId ?? '').trim();
const openaiBatchId = String(base.openaiBatchId ?? '').trim();
const openaiKey = String(base.openaiKey ?? '').trim();
const openaiModel = String(base.openaiModel ?? 'gpt-4.1-mini').trim();
const batchInputPrice = Number($env.OPENAI_BATCH_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? $env.OPENAI_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const batchOutputPrice = Number($env.OPENAI_BATCH_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? $env.OPENAI_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const pollIntervalMs = Math.max(3000, Number($env.BATCH_POLLER_INTERVAL_MS ?? 20000));
const maxLoops = Math.max(1, Number($env.BATCH_POLLER_MAX_LOOPS ?? 45));
const runnerTaskTimeoutSec = Math.max(60, Number($env.N8N_RUNNERS_TASK_TIMEOUT ?? 300));
const runnerSafetyBufferSec = 20;
const pollBudgetMs = Math.max(1000, (runnerTaskTimeoutSec - runnerSafetyBufferSec) * 1000);
const maxLoopsByRunnerBudget = Math.max(1, Math.floor(pollBudgetMs / pollIntervalMs));
const effectiveMaxLoops = Math.max(1, Math.min(maxLoops, maxLoopsByRunnerBudget));

const escapeSql = (v) => String(v ?? '').replace(/'/g, "''");
const failSql = (message) => {
  const msg = escapeSql(String(message ?? 'Batch poll failed').slice(0, 900));
  return `BEGIN;\nUPDATE batch_windows SET status='failed', completed_at=NOW() WHERE id='${escapeSql(batchId)}';\nUPDATE summary_jobs SET status='failed', error_message='${msg}', completed_at=NOW(), updated_at=NOW() WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','batched','processing');\nUPDATE batch_items SET status='failed' WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','processing');\nCOMMIT;`;
};

if (!batchId) return [{ json: { batchId: '', terminalStatus: 'failed', resultSql: 'SELECT 1;' } }];
if (!openaiBatchId || !openaiKey) return [{ json: { batchId, terminalStatus: 'failed', resultSql: failSql('Missing batch context for poll stage') } }];

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const parseOutputText = (raw) => {
  if (!raw || typeof raw !== 'object') return '';
  if (typeof raw.output_text === 'string' && raw.output_text.trim()) return raw.output_text.trim();
  const output = Array.isArray(raw.output) ? raw.output : [];
  const chunks = [];
  for (const item of output) {
    const content = Array.isArray(item?.content) ? item.content : [];
    for (const piece of content) {
      if (piece?.type === 'output_text' && typeof piece.text === 'string') chunks.push(piece.text);
    }
  }
  return chunks.join('\n').trim();
};
const estimateBatchCost = (inTokens, outTokens) => {
  const inputCost = (Number(inTokens) / 1_000_000) * batchInputPrice;
  const outputCost = (Number(outTokens) / 1_000_000) * batchOutputPrice;
  return Number((inputCost + outputCost).toFixed(6));
};

try {
  let terminal = null;
  let remote = null;

  for (let i = 0; i < effectiveMaxLoops; i += 1) {
    remote = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.openai.com/v1/batches/${encodeURIComponent(openaiBatchId)}`,
      headers: { Authorization: `Bearer ${openaiKey}` },
      json: true,
    });

    const status = String(remote.status ?? '').trim();
    if (status === 'completed') { terminal = status; break; }
    if (['failed', 'expired', 'cancelled', 'cancelling'].includes(status)) { terminal = status; break; }
    await sleep(pollIntervalMs);
  }

  if (!terminal) {
    const timeoutMsg = `Batch polling timed out before terminal status (loops=${effectiveMaxLoops}, intervalMs=${pollIntervalMs}, runnerTimeoutSec=${runnerTaskTimeoutSec}). Increase N8N_RUNNERS_TASK_TIMEOUT or lower BATCH_POLLER_INTERVAL_MS/BATCH_POLLER_MAX_LOOPS.`;
    return [{ json: { batchId, terminalStatus: 'failed', resultSql: failSql(timeoutMsg) } }];
  }

  const sql = ['BEGIN;'];
  if (terminal !== 'completed') {
    const mapped = terminal === 'expired' ? 'expired' : 'failed';
    const errMsg = escapeSql(String(remote?.errors?.[0]?.message ?? `OpenAI batch ended with status ${terminal}`));
    sql.push(`UPDATE batch_windows SET status='${mapped}', completed_at=NOW(), error_file_id=COALESCE(error_file_id, NULLIF('${escapeSql(remote?.error_file_id ?? '')}','')) WHERE id='${escapeSql(batchId)}';`);
    sql.push(`UPDATE summary_jobs SET status='${mapped === 'expired' ? 'expired' : 'failed'}', error_message='${errMsg}', completed_at=NOW(), updated_at=NOW() WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','batched','processing');`);
    sql.push(`UPDATE batch_items SET status='failed' WHERE batch_id='${escapeSql(batchId)}' AND status IN ('queued','processing');`);
    sql.push('COMMIT;');
    return [{ json: { batchId, terminalStatus: mapped, resultSql: sql.join('\n') } }];
  }

  const outputFileId = String(remote.output_file_id ?? '').trim();
  if (!outputFileId) return [{ json: { batchId, terminalStatus: 'failed', resultSql: failSql('Batch completed without output_file_id') } }];

  const outputText = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.openai.com/v1/files/${encodeURIComponent(outputFileId)}/content`,
    headers: { Authorization: `Bearer ${openaiKey}` },
    json: false,
    encoding: 'utf8',
  });

  const lines = String(outputText ?? '').split('\n').map((x) => x.trim()).filter(Boolean);

  for (const line of lines) {
    let parsed;
    try { parsed = JSON.parse(line); } catch { continue; }

    const jobId = String(parsed.custom_id ?? '').trim();
    if (!jobId) continue;

    const statusCode = Number(parsed?.response?.status_code ?? 0);
    const body = parsed?.response?.body ?? null;

    if (statusCode >= 200 && statusCode < 300 && body) {
      const summaryText = parseOutputText(body) || 'No summary generated.';
      const usage = body.usage ?? {};
      const inTok = Number(usage.input_tokens ?? 0);
      const outTok = Number(usage.output_tokens ?? 0);
      const totalTok = Number(usage.total_tokens ?? (inTok + outTok));
      const reqId = String(body.id ?? '').trim();
      const model = String(body.model ?? openaiModel);
      const cost = estimateBatchCost(inTok, outTok);
      const raw = escapeSql(JSON.stringify(body));

      sql.push(`UPDATE summary_jobs SET status='completed', error_message=NULL, openai_request_id=COALESCE(openai_request_id,NULLIF('${escapeSql(reqId)}','')), completed_at=NOW(), updated_at=NOW() WHERE id='${escapeSql(jobId)}';`);
      sql.push(`UPDATE batch_items SET status='completed' WHERE batch_id='${escapeSql(batchId)}' AND job_id='${escapeSql(jobId)}';`);
      sql.push(`INSERT INTO summary_results (job_id,user_id,summary_text,model,provider,input_tokens,output_tokens,total_tokens,latency_ms,cost_est_usd,raw_response_json,created_at)
SELECT j.id, j.user_id, '${escapeSql(summaryText)}', '${escapeSql(model)}', 'openai', ${inTok}, ${outTok}, ${totalTok}, NULL, ${cost}, '${raw}'::jsonb, NOW()
FROM summary_jobs j WHERE j.id='${escapeSql(jobId)}'
ON CONFLICT (job_id) DO UPDATE SET
  summary_text=EXCLUDED.summary_text,
  model=EXCLUDED.model,
  provider=EXCLUDED.provider,
  input_tokens=EXCLUDED.input_tokens,
  output_tokens=EXCLUDED.output_tokens,
  total_tokens=EXCLUDED.total_tokens,
  latency_ms=EXCLUDED.latency_ms,
  cost_est_usd=EXCLUDED.cost_est_usd,
  raw_response_json=EXCLUDED.raw_response_json,
  created_at=NOW();`);
    } else {
      const message = escapeSql(String(parsed?.error?.message ?? `Batch item failed (${statusCode || 'unknown'})`));
      sql.push(`UPDATE summary_jobs SET status='failed', error_message='${message}', completed_at=NOW(), updated_at=NOW() WHERE id='${escapeSql(jobId)}';`);
      sql.push(`UPDATE batch_items SET status='failed' WHERE batch_id='${escapeSql(batchId)}' AND job_id='${escapeSql(jobId)}';`);
    }
  }

  sql.push(`UPDATE batch_windows SET status='completed', completed_at=NOW(), output_file_id=COALESCE(output_file_id,NULLIF('${escapeSql(outputFileId)}','')), error_file_id=COALESCE(error_file_id,NULLIF('${escapeSql(remote?.error_file_id ?? '')}','')) WHERE id='${escapeSql(batchId)}';`);
  sql.push('COMMIT;');
  return [{ json: { batchId, terminalStatus: 'completed', resultSql: sql.join('\n') } }];
} catch (error) {
  return [{ json: { batchId, terminalStatus: 'failed', resultSql: failSql(String(error?.message ?? 'Batch poll failed')) } }];
}

const input = $json.body ?? $json;
const reqHeaders = $json.headers ?? {};
const benchmarkRunId = String(input.benchmarkRunId ?? '').trim();
if (!benchmarkRunId) throw new Error('benchmarkRunId is required for wf_admin_benchmark_runner');

const expectedToken = String($env.INTERNAL_API_TOKEN ?? '').trim();
const providedToken = String(reqHeaders['x-internal-token'] ?? reqHeaders['X-Internal-Token'] ?? '').trim();
if (!expectedToken || providedToken !== expectedToken) throw new Error('Invalid internal token for wf_admin_benchmark_runner');

const appBase = String($env.APP_INTERNAL_BASE_URL ?? 'http://app:8080').replace(/\/+$/, '');
const openaiKey = String($env.OPENAI_API_KEY ?? '').trim();
const openaiModel = String($env.OPENAI_MODEL ?? 'gpt-4.1-mini').trim();
const completionWindow = String($env.OPENAI_BATCH_COMPLETION_WINDOW ?? '24h').trim();
const inputPrice = Number($env.OPENAI_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const outputPrice = Number($env.OPENAI_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const batchInputPrice = Number($env.OPENAI_BATCH_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? $env.OPENAI_INPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const batchOutputPrice = Number($env.OPENAI_BATCH_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? $env.OPENAI_OUTPUT_TOKEN_PRICE_PER_MILLION_USD ?? '0');
const repetitions = Math.max(1, Number(input.repetitions ?? $env.BENCHMARK_REPETITIONS ?? 3));
const jobsPerRun = Math.max(1, Number(input.jobsPerRun ?? $env.BENCHMARK_JOBS_PER_RUN ?? 20));
const maxBatchSize = Math.max(1, Number(input.maxBatchSize ?? $env.MAX_BATCH_SIZE ?? 20));
const maxWaitSeconds = Math.max(1, Number(input.maxWaitSeconds ?? $env.MAX_WAIT_SECONDS ?? 60));
const pollIntervalMs = Math.max(5000, Number($env.BENCHMARK_BATCH_POLL_INTERVAL_MS ?? 20000));
const batchMaxWaitMs = Math.max(60000, Number($env.BENCHMARK_BATCH_MAX_WAIT_MS ?? 7200000));
const datasetTier = String(input.datasetTier ?? 'all').trim().toLowerCase();
if (!openaiKey) throw new Error('OPENAI_API_KEY is required in n8n environment for benchmark workflow.');

const parseMaybeJson = (value) => {
  if (value == null) return {};
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch { return { raw: value }; }
  }
  return { raw: String(value) };
};

const postJson = async (url, body, headers = {}) => this.helpers.httpRequest({ method: 'POST', url, headers, body, json: true });
const getJson = async (url, headers = {}) => this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
const getText = async (url, headers = {}) => this.helpers.httpRequest({ method: 'GET', url, headers, json: false, encoding: 'utf8' });
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const uploadMultipart = async ({ filename, content, contentType = 'application/jsonl' }) => {
  return this.helpers.httpRequest({
    method: 'POST',
    url: `${appBase}/api/internal/openai/files/upload-text`,
    headers: {
      'x-internal-token': expectedToken,
      'Content-Type': 'application/json',
    },
    body: {
      purpose: 'batch',
      filename,
      contentType,
      content,
    },
    json: true,
  });
};

const estimateCost = (inTokens, outTokens) => {
  const inputCost = (Number(inTokens) / 1_000_000) * inputPrice;
  const outputCost = (Number(outTokens) / 1_000_000) * outputPrice;
  return Number((inputCost + outputCost).toFixed(6));
};

const estimateBatchCost = (inTokens, outTokens) => {
  const inputCost = (Number(inTokens) / 1_000_000) * batchInputPrice;
  const outputCost = (Number(outTokens) / 1_000_000) * batchOutputPrice;
  return Number((inputCost + outputCost).toFixed(6));
};

const percentile = (values, p) => {
  if (!Array.isArray(values) || values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const idx = Math.min(sorted.length - 1, Math.max(0, Math.ceil((p / 100) * sorted.length) - 1));
  return sorted[idx];
};

const parseOutputText = (raw) => {
  if (!raw || typeof raw !== 'object') return '';
  if (typeof raw.output_text === 'string' && raw.output_text.trim()) return raw.output_text.trim();
  const output = Array.isArray(raw.output) ? raw.output : [];
  const chunks = [];
  for (const item of output) {
    const content = Array.isArray(item?.content) ? item.content : [];
    for (const piece of content) {
      if (piece?.type === 'output_text' && typeof piece.text === 'string') chunks.push(piece.text);
    }
  }
  return chunks.join('\n').trim();
};

const updateBenchmarkStatus = async (payload) => {
  await postJson(`${appBase}/api/internal/benchmarks/${encodeURIComponent(benchmarkRunId)}/status`, payload, {
    'Content-Type': 'application/json',
    'x-internal-token': expectedToken,
  });
};

const buildBenchmarkInputsForTier = (tier, count) => {
  const tierConfig = {
    S: { sections: 6, repeat: 20, profile: 'short technical memo (1-3 pages)' },
    M: { sections: 14, repeat: 55, profile: 'medium engineering report (8-12 pages)' },
    L: { sections: 30, repeat: 95, profile: 'long architecture dossier (25-35 pages)' },
  };
  const cfg = tierConfig[tier] ?? tierConfig.S;
  return Array.from({ length: count }, (_unused, i) => {
    const intro = `Benchmark document ${i + 1} for tier ${tier}: ${cfg.profile}.`;
    const sections = Array.from({ length: cfg.sections }, (_u, idx) => `Section ${idx + 1}: This section explains distributed workflow design, queue backpressure management, idempotent ingestion, and operational cost controls for asynchronous AI workloads.`).join(' ');
    const bullets = Array.from({ length: cfg.repeat }, (_u, idx) => `Point ${idx + 1}: Prioritize reliable retries, deterministic status transitions, and bounded time-to-completion.`).join(' ');
    return `${intro} ${sections} ${bullets}`;
  });
};

const runSyncRepetition = async ({ tier, repetition }) => {
  const inputs = buildBenchmarkInputsForTier(tier, jobsPerRun);
  const latencies = [];
  let totalCostEstUsd = 0;
  let jobsCompleted = 0;
  const started = Date.now();

  for (let i = 0; i < inputs.length; i += 1) {
    const reqBody = {
      model: openaiModel,
      input: [
        { role: 'system', content: [{ type: 'input_text', text: 'You are a concise technical summarizer. Summarize the document in 6-10 bullet points and end with one-paragraph executive summary.' }] },
        { role: 'user', content: [{ type: 'input_text', text: `Summarize this PDF text:\n\n${inputs[i]}` }] },
      ],
      max_output_tokens: 550,
      metadata: { template: 'template_2_benchmark', mode: 'sync', tier, repetition: String(repetition), index: String(i + 1) },
    };

    const oneStart = Date.now();
    const raw = await postJson('https://api.openai.com/v1/responses', reqBody, {
      Authorization: `Bearer ${openaiKey}`,
      'Content-Type': 'application/json',
    });

    const summaryText = parseOutputText(raw) || 'No summary generated.';
    const usage = raw.usage ?? {};
    const inputTokens = Number(usage.input_tokens ?? 0);
    const outputTokens = Number(usage.output_tokens ?? 0);

    jobsCompleted += 1;
    latencies.push(Date.now() - oneStart);
    totalCostEstUsd += estimateCost(inputTokens, outputTokens);
    if (!summaryText) throw new Error('Benchmark sync response returned empty summary');
  }

  const totalTimeMs = Date.now() - started;
  return {
    mode: 'sync', strategy: 'sync_baseline', datasetTier: tier,
    jobsSubmitted: jobsPerRun, jobsCompleted, totalTimeMs,
    avgLatencyMs: latencies.length ? Math.floor(latencies.reduce((a, n) => a + n, 0) / latencies.length) : 0,
    p95LatencyMs: percentile(latencies, 95),
    totalCostEstUsd: Number(totalCostEstUsd.toFixed(6)),
  };
};

const waitForBatch = async (openaiBatchId) => {
  const started = Date.now();
  while (true) {
    const payload = await getJson(`https://api.openai.com/v1/batches/${encodeURIComponent(openaiBatchId)}`, { Authorization: `Bearer ${openaiKey}` });
    const status = String(payload.status ?? '').trim();
    if (status === 'completed') return payload;
    if (['failed', 'expired', 'cancelled', 'cancelling'].includes(status)) throw new Error(`Benchmark batch ended with status '${status}'`);
    if (Date.now() - started > batchMaxWaitMs) throw new Error('Benchmark batch wait timed out');
    await sleep(pollIntervalMs);
  }
};

const runBatchRepetition = async ({ tier, strategy, repetition }) => {
  const inputs = buildBenchmarkInputsForTier(tier, jobsPerRun);
  const items = inputs.map((text, index) => ({ customId: `benchmark-${strategy}-${tier}-r${repetition}-j${index + 1}`, text }));

    const lines = items.map((item) => JSON.stringify({
    custom_id: item.customId, method: 'POST', url: '/v1/responses',
    body: {
      model: openaiModel,
      input: [
        { role: 'system', content: [{ type: 'input_text', text: 'You are a concise technical summarizer. Summarize the document in 6-10 bullet points and end with one-paragraph executive summary.' }] },
        { role: 'user', content: [{ type: 'input_text', text: `Summarize this PDF text:\n\n${item.text}` }] },
      ],
      max_output_tokens: 550,
      metadata: { template: 'template_2_benchmark', mode: 'batch', tier, strategy, repetition: String(repetition) },
    },
  }));

  const start = Date.now();

  const uploadJson = await uploadMultipart({
    filename: `benchmark-${tier}-${strategy}-r${repetition}.jsonl`,
    content: `${lines.join("\n")}\n`,
    contentType: 'application/jsonl',
  });

  const inputFileId = String(uploadJson?.file?.id ?? uploadJson?.id ?? '').trim();
  if (!inputFileId) throw new Error(`Benchmark batch input upload returned no file id: ${JSON.stringify(uploadJson).slice(0, 300)}`);

  const submitJson = await postJson('https://api.openai.com/v1/batches', {
    input_file_id: inputFileId, endpoint: '/v1/responses', completion_window: completionWindow,
    metadata: { template: 'template_2_benchmark', tier, strategy, repetition: String(repetition) },
  }, { Authorization: `Bearer ${openaiKey}`, 'Content-Type': 'application/json' });

  const openaiBatchId = String(submitJson.id ?? '').trim();
  if (!openaiBatchId) throw new Error('Benchmark batch submit returned no batch id');

  const completed = await waitForBatch(openaiBatchId);
  const outputFileId = String(completed.output_file_id ?? '').trim();
  if (!outputFileId) throw new Error('Benchmark batch completed without output_file_id');

  const outputText = await getText(`https://api.openai.com/v1/files/${encodeURIComponent(outputFileId)}/content`, { Authorization: `Bearer ${openaiKey}` });

  const outputMap = new Map();
  for (const line of String(outputText).split('\n')) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    try {
      const parsed = JSON.parse(trimmed);
      const customId = String(parsed.custom_id ?? '').trim();
      if (!customId) continue;
      outputMap.set(customId, parsed);
    } catch {
      // ignore malformed lines
    }
  }

  let jobsCompleted = 0;
  let totalCostEstUsd = 0;
  for (const item of items) {
    const outputItem = outputMap.get(item.customId);
    const statusCode = Number(outputItem?.response?.status_code ?? 0);
    const body = outputItem?.response?.body ?? null;
    if (statusCode < 200 || statusCode >= 300 || !body) continue;

    const usage = body.usage ?? {};
    const inputTokens = Number(usage.input_tokens ?? 0);
    const outputTokens = Number(usage.output_tokens ?? 0);
    jobsCompleted += 1;
    totalCostEstUsd += estimateBatchCost(inputTokens, outputTokens);
  }

  const totalTimeMs = Date.now() - start;
  const avgLatencyMs = jobsCompleted > 0 ? Math.floor(totalTimeMs / jobsCompleted) : 0;
  return {
    mode: 'batch', strategy, datasetTier: tier,
    jobsSubmitted: jobsPerRun, jobsCompleted, totalTimeMs, avgLatencyMs,
    p95LatencyMs: avgLatencyMs,
    totalCostEstUsd: Number(totalCostEstUsd.toFixed(6)),
  };
};

const pickMedianSample = (samples) => {
  if (!Array.isArray(samples) || samples.length === 0) throw new Error('Cannot pick median sample from empty array');
  const sorted = [...samples].sort((a, b) => a.totalTimeMs - b.totalTimeMs);
  return sorted[Math.floor(sorted.length / 2)];
};

const tiers = datasetTier === 'all' ? ['S', 'M', 'L'] : [datasetTier.toUpperCase()];
const scenarios = [
  { mode: 'sync', strategy: 'sync_baseline' },
  { mode: 'batch', strategy: 'count_only' },
];

await updateBenchmarkStatus({ status: 'processing' });

try {
  const matrix = [];
  const rawRepetitions = [];

  for (const tier of tiers) {
    for (const scenario of scenarios) {
      const reps = [];
      for (let repetition = 1; repetition <= repetitions; repetition += 1) {
        reps.push(scenario.mode === 'sync'
          ? await runSyncRepetition({ tier, repetition })
          : await runBatchRepetition({ tier, strategy: scenario.strategy, repetition }));
      }
      rawRepetitions.push({ tier, mode: scenario.mode, strategy: scenario.strategy, repetitions: reps });
      matrix.push(pickMedianSample(reps));
    }
  }

  const fastest = [...matrix].sort((a, b) => a.totalTimeMs - b.totalTimeMs)[0];
  const cheapest = [...matrix].sort((a, b) => a.totalCostEstUsd - b.totalCostEstUsd)[0];

  const report = {
    generatedAt: new Date().toISOString(),
    execution: 'real_openai_via_n8n',
    settings: { repetitions, jobsPerRun, openaiModel, completionWindow, maxBatchSize, maxWaitSeconds },
    tiers,
    defaultRecommendation: { speed: fastest, cost: cheapest },
    notes: [
      'All benchmark scenarios were executed against live OpenAI APIs from n8n.',
      'Batch p95 latency is normalized from batch completion time because per-item latency is not returned by Batch API outputs.',
      'Compare sync baseline and count_only batch before changing runtime defaults.',
    ],
    matrix,
    rawRepetitions,
  };

  await updateBenchmarkStatus({ status: 'completed', samples: matrix, report });
  return [{ json: { ok: true, benchmarkRunId, status: 'completed', samples: matrix.length } }];
} catch (error) {
  const msg = String(error?.message ?? 'wf_admin_benchmark_runner failed');
  await updateBenchmarkStatus({ status: 'failed', error: msg, report: { error: msg, failedAt: new Date().toISOString() } });
  throw error;
}
